"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { Package, ArrowLeft, Check, User, Phone, Mail, MapPin, Loader2, QrCode } from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";

type Item = {
  id: string;
  name: string;
  description?: string | null;
  qrCode: string;
  status: string;
  borrowerName?: string | null;
  borrowerPhone?: string | null;
  borrowerEmail?: string | null;
  lentAt?: string | null;
  returnedAt?: string | null;
  gemach: {
    id: string;
    name: string;
    phone: string;
    email?: string | null;
    city: string;
    state: string;
  };
};

export default function ScanPage() {
  const { qrCode } = useParams<{ qrCode: string }>();
  const [item, setItem] = useState<Item | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Borrow form
  const [step, setStep] = useState<"view" | "borrow" | "done">("view");
  const [borrowerName, setBorrowerName] = useState("");
  const [borrowerPhone, setBorrowerPhone] = useState("");
  const [borrowerEmail, setBorrowerEmail] = useState("");

  useEffect(() => {
    fetchItem();
  }, [qrCode]);

  async function fetchItem() {
    try {
      setLoading(true);
      const res = await fetch(`/api/items/qr/${qrCode}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Not found");
      setItem(data.item);
      setError(null);
      if (data.item.status === "lent") setStep("view");
      if (data.item.status === "returned") setStep("done");
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  async function handleBorrow() {
    if (!borrowerName.trim()) {
      toast.error("Please enter your name");
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch(`/api/items/qr/${qrCode}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "borrow",
          borrowerName: borrowerName.trim(),
          borrowerPhone: borrowerPhone.trim() || undefined,
          borrowerEmail: borrowerEmail.trim() || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      setItem(data.item);
      setSuccessMessage(data.message);
      setStep("done");
      toast.success(data.message);
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSubmitting(false);
    }
  }

  async function handleReturn() {
    setSubmitting(true);
    try {
      const res = await fetch(`/api/items/qr/${qrCode}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "return" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      setItem(data.item);
      setSuccessMessage(data.message);
      setStep("done");
      toast.success(data.message);
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSubmitting(false);
    }
  }

  // Loading
  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-950">
        <div className="text-center">
          <Loader2 className="mx-auto h-10 w-10 animate-spin text-orange-400" />
          <p className="mt-4 text-sm text-slate-400">Loading item...</p>
        </div>
      </div>
    );
  }

  // Error
  if (error) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-950 px-4">
        <div className="text-center max-w-sm">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-red-500/10">
            <Package className="h-8 w-8 text-red-400" />
          </div>
          <h2 className="text-lg font-semibold text-white">Item Not Found</h2>
          <p className="mt-2 text-sm text-slate-400">{error}</p>
          <Link
            href="/"
            className="mt-6 inline-flex items-center gap-2 rounded-lg bg-slate-700 px-4 py-2 text-sm font-medium text-white hover:bg-slate-600 transition"
          >
            <ArrowLeft className="h-4 w-4" /> Back to Home
          </Link>
        </div>
      </div>
    );
  }

  if (!item) return null;

  const isAvailable = item.status === "available";
  const isLent = item.status === "lent";

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      {/* Header */}
      <header className="border-b border-slate-800 px-4 py-4">
        <div className="mx-auto flex max-w-md items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-orange-500">
              <QrCode className="h-4 w-4 text-white" />
            </div>
            <div>
              <p className="text-xs text-slate-400">Gemach Connect</p>
              <p className="text-sm font-semibold">Item Tracker</p>
            </div>
          </div>
          <a
            href="https://trydockly.com"
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-slate-500 hover:text-orange-400 transition"
          >
            by Dockly
          </a>
        </div>
      </header>

      <main className="mx-auto max-w-md px-4 py-8">
        {/* Status Banner */}
        {step !== "done" && (
          <div
            className={`mb-6 rounded-xl px-4 py-3 text-sm font-medium ${
              isAvailable
                ? "bg-green-500/10 text-green-400 border border-green-500/20"
                : "bg-amber-500/10 text-amber-400 border border-amber-500/20"
            }`}
          >
            {isAvailable && (
              <span className="flex items-center gap-2">
                <span className="flex h-1.5 w-1.5 rounded-full bg-green-400 animate-pulse" />
                Available — ready to borrow
              </span>
            )}
            {isLent && (
              <span className="flex items-center gap-2">
                <span className="flex h-1.5 w-1.5 rounded-full bg-amber-400" />
                Currently borrowed by {item.borrowerName}
              </span>
            )}
          </div>
        )}

        {/* Success State */}
        {step === "done" && (
          <div className="mb-6 rounded-xl bg-green-500/10 border border-green-500/20 px-4 py-6 text-center">
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-green-500/20">
              <Check className="h-7 w-7 text-green-400" />
            </div>
            <h2 className="mt-4 text-lg font-bold text-green-400">
              {item.status === "lent" ? "Borrowed!" : "Returned!"}
            </h2>
            <p className="mt-1 text-sm text-slate-300">{successMessage}</p>
          </div>
        )}

        {/* Item Card */}
        <div className="rounded-xl border border-slate-800 bg-slate-900 p-5">
          <div className="flex items-start gap-3">
            <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-lg bg-orange-500/10">
              <Package className="h-5 w-5 text-orange-400" />
            </div>
            <div>
              <h1 className="text-lg font-bold">{item.name}</h1>
              {item.description && (
                <p className="mt-1 text-sm text-slate-400">{item.description}</p>
              )}
            </div>
          </div>

          <div className="mt-4 space-y-2 border-t border-slate-800 pt-4">
            <div className="flex items-center gap-2 text-sm text-slate-400">
              <MapPin className="h-4 w-4 text-slate-500" />
              {item.gemach.name} — {item.gemach.city}, {item.gemach.state}
            </div>
            {item.gemach.phone && (
              <div className="flex items-center gap-2 text-sm text-slate-400">
                <Phone className="h-4 w-4 text-slate-500" />
                {item.gemach.phone}
              </div>
            )}
            {item.gemach.email && (
              <div className="flex items-center gap-2 text-sm text-slate-400">
                <Mail className="h-4 w-4 text-slate-500" />
                {item.gemach.email}
              </div>
            )}
          </div>

          {/* Borrower info if lent */}
          {isLent && step !== "done" && (
            <div className="mt-4 border-t border-slate-800 pt-4 space-y-2">
              <p className="text-xs font-medium uppercase tracking-wide text-slate-500">Borrower</p>
              <div className="flex items-center gap-2 text-sm">
                <User className="h-4 w-4 text-slate-500" />
                <span className="text-slate-300">{item.borrowerName}</span>
              </div>
              {item.borrowerPhone && (
                <div className="flex items-center gap-2 text-sm">
                  <Phone className="h-4 w-4 text-slate-500" />
                  <span className="text-slate-300">{item.borrowerPhone}</span>
                </div>
              )}
              {item.lentAt && (
                <p className="text-xs text-slate-500">
                  Borrowed {new Date(item.lentAt).toLocaleDateString()}
                </p>
              )}
            </div>
          )}

          {/* Done state details */}
          {step === "done" && item.status === "lent" && (
            <div className="mt-4 border-t border-slate-800 pt-4">
              <p className="text-xs text-slate-500">
                Borrowed on {new Date(item.lentAt!).toLocaleDateString()}
              </p>
            </div>
          )}
        </div>

        {/* Actions */}
        {step === "view" && isAvailable && (
          <button
            onClick={() => setStep("borrow")}
            className="mt-4 w-full rounded-xl bg-orange-500 px-4 py-3 font-semibold text-white hover:bg-orange-600 transition active:scale-[0.98]"
          >
            Borrow This Item
          </button>
        )}

        {step === "view" && isLent && (
          <button
            onClick={handleReturn}
            disabled={submitting}
            className="mt-4 w-full rounded-xl bg-green-600 px-4 py-3 font-semibold text-white hover:bg-green-700 transition active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {submitting ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" /> Processing...
              </>
            ) : (
              <>
                <Check className="h-5 w-5" /> Return This Item
              </>
            )}
          </button>
        )}

        {/* Borrow Form */}
        {step === "borrow" && (
          <div className="mt-4 rounded-xl border border-slate-800 bg-slate-900 p-5">
            <h3 className="font-semibold text-lg">Your Information</h3>
            <p className="text-sm text-slate-400 mt-1">The gemach owner will be notified.</p>

            <div className="mt-4 space-y-3">
              <div>
                <label className="text-sm font-medium text-slate-300 block mb-1">Your Name *</label>
                <input
                  type="text"
                  value={borrowerName}
                  onChange={(e) => setBorrowerName(e.target.value)}
                  className="w-full rounded-lg border border-slate-700 bg-slate-800 px-3 py-2.5 text-white text-sm placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 focus:border-orange-500"
                  placeholder="Full name"
                  autoFocus
                />
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 block mb-1">Phone</label>
                <input
                  type="tel"
                  value={borrowerPhone}
                  onChange={(e) => setBorrowerPhone(e.target.value)}
                  className="w-full rounded-lg border border-slate-700 bg-slate-800 px-3 py-2.5 text-white text-sm placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 focus:border-orange-500"
                  placeholder="(Optional)"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 block mb-1">Email</label>
                <input
                  type="email"
                  value={borrowerEmail}
                  onChange={(e) => setBorrowerEmail(e.target.value)}
                  className="w-full rounded-lg border border-slate-700 bg-slate-800 px-3 py-2.5 text-white text-sm placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-orange-500/50 focus:border-orange-500"
                  placeholder="(Optional)"
                />
              </div>

              <div className="flex gap-3 pt-2">
                <button
                  onClick={() => setStep("view")}
                  className="flex-1 rounded-xl border border-slate-700 px-4 py-2.5 text-sm font-medium text-slate-300 hover:bg-slate-800 transition"
                >
                  Cancel
                </button>
                <button
                  onClick={handleBorrow}
                  disabled={submitting}
                  className="flex-1 rounded-xl bg-orange-500 px-4 py-2.5 text-sm font-semibold text-white hover:bg-orange-600 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {submitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" /> Confirming...
                    </>
                  ) : (
                    "Confirm Borrow"
                  )}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Done state CTA */}
        {step === "done" && (
          <div className="mt-4 space-y-3">
            {item.status === "lent" && (
              <p className="text-center text-sm text-slate-500">
                Scan this code again when you're ready to return the item.
              </p>
            )}
            <Link
              href="/"
              className="w-full rounded-xl border border-slate-700 px-4 py-3 text-center block text-sm font-medium text-slate-300 hover:bg-slate-800 transition"
            >
              <ArrowLeft className="h-4 w-4 inline mr-1" /> Back to Home
            </Link>
          </div>
        )}

        {/* Footer */}
        <p className="mt-8 text-center text-xs text-slate-600">
          Powered by{" "}
          <a
            href="https://trydockly.com"
            target="_blank"
            rel="noopener noreferrer"
            className="text-orange-400 hover:text-orange-300 underline underline-offset-2"
          >
            Dockly
          </a>
          {" "}— QR tracking for gemachs
        </p>
      </main>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import {
  Package,
  ArrowUpRight,
  Check,
  Clock,
  RotateCcw,
  User,
  Phone,
  Mail,
  ExternalLink,
  QrCode,
  Filter,
} from "lucide-react";
import { EmptyState } from "@/components/EmptyState";
import { CardSkeleton } from "@/components/Skeleton";

type Item = {
  id: string;
  name: string;
  description?: string | null;
  qrCode: string;
  status: string;
  borrowerName?: string | null;
  borrowerPhone?: string | null;
  borrowerEmail?: string | null;
  lentAt?: string | null;
  returnedAt?: string | null;
  createdAt: string;
  gemach: { id: string; name: string };
};

type Stats = { available: number; lent: number; returned: number; total: number };

export default function ItemsDashboard() {
  const [items, setItems] = useState<Item[]>([]);
  const [stats, setStats] = useState<Stats>({ available: 0, lent: 0, returned: 0, total: 0 });
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<string>("all");

  useEffect(() => {
    fetch("/api/items")
      .then((r) => r.json())
      .then((d) => {
        setItems(d.items || []);
        setStats(d.stats || { available: 0, lent: 0, returned: 0, total: 0 });
        setLoading(false);
      });
  }, []);

  const filtered = filter === "all" ? items : items.filter((i) => i.status === filter);

  const statCards = [
    {
      label: "Available",
      count: stats.available,
      icon: Package,
      color: "bg-green-100 text-green-600",
      border: "border-l-green-500",
      filter: "available",
    },
    {
      label: "Borrowed",
      count: stats.lent,
      icon: Clock,
      color: "bg-amber-100 text-amber-600",
      border: "border-l-amber-500",
      filter: "lent",
    },
    {
      label: "Returned",
      count: stats.returned,
      icon: RotateCcw,
      color: "bg-blue-100 text-blue-600",
      border: "border-l-blue-500",
      filter: "returned",
    },
  ];

  if (loading) {
    return (
      <div className="max-w-6xl mx-auto space-y-6">
        <div className="grid gap-4 md:grid-cols-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="card p-5"><CardSkeleton /></div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Items</h1>
          <p className="text-gray-500 mt-1">Track all your gemach items and their status.</p>
        </div>
      </div>

      {/* Stats — Dockly-style */}
      <div className="grid gap-4 md:grid-cols-3">
        {statCards.map((s) => (
          <button
            key={s.label}
            onClick={() => setFilter(filter === s.filter ? "all" : s.filter)}
            className={`card p-5 flex items-center gap-4 border-l-4 ${s.border} text-left hover:shadow-md transition ${
              filter === s.filter ? "ring-2 ring-offset-1 ring-gray-200" : ""
            }`}
          >
            <div className={`flex h-12 w-12 items-center justify-center rounded-xl ${s.color}`}>
              <s.icon className="h-6 w-6" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{s.count}</p>
              <p className="text-sm text-gray-500">{s.label}</p>
            </div>
          </button>
        ))}
      </div>

      {/* Filter bar */}
      {stats.total > 0 && (
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-gray-400" />
          {["all", "available", "lent", "returned"].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`rounded-full px-3 py-1 text-xs font-medium transition ${
                filter === f
                  ? "bg-gray-900 text-white"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              {f === "all" ? "All" : f.charAt(0).toUpperCase() + f.slice(1)}
            </button>
          ))}
        </div>
      )}

      {/* Items list */}
      {filtered.length === 0 ? (
        <EmptyState
          icon={Package}
          title={stats.total === 0 ? "No items yet" : "No matching items"}
          description={
            stats.total === 0
              ? "Add items to your gemachs to start tracking them with QR codes."
              : "Try a different filter."
          }
          action={
            stats.total === 0
              ? { label: "Go to My Gemachs", href: "/dashboard/my-gemachs" }
              : undefined
          }
        />
      ) : (
        <div className="grid gap-3 md:grid-cols-2">
          {filtered.map((item) => (
            <Link
              key={item.id}
              href={`/dashboard/items/${item.id}`}
              className="card p-4 hover:shadow-md transition group"
            >
              <div className="flex items-start gap-3">
                <div
                  className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl ${
                    item.status === "available"
                      ? "bg-green-100 text-green-600"
                      : item.status === "lent"
                      ? "bg-amber-100 text-amber-600"
                      : "bg-blue-100 text-blue-600"
                  }`}
                >
                  {item.status === "available" ? (
                    <Package className="h-5 w-5" />
                  ) : item.status === "lent" ? (
                    <Clock className="h-5 w-5" />
                  ) : (
                    <Check className="h-5 w-5" />
                  )}
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-semibold text-gray-900 truncate group-hover:text-primary-600 transition">
                      {item.name}
                    </p>
                    <span
                      className={`text-xs font-medium px-1.5 py-0.5 rounded-full flex-shrink-0 ${
                        item.status === "available"
                          ? "bg-green-50 text-green-700"
                          : item.status === "lent"
                          ? "bg-amber-50 text-amber-700"
                          : "bg-blue-50 text-blue-700"
                      }`}
                    >
                      {item.status === "available"
                        ? "Available"
                        : item.status === "lent"
                        ? "Borrowed"
                        : "Returned"}
                    </span>
                  </div>
                  <p className="text-xs text-gray-400 mt-1">{item.gemach.name}</p>
                  {item.description && (
                    <p className="text-xs text-gray-500 mt-1 line-clamp-1">{item.description}</p>
                  )}
                  {item.status === "lent" && item.borrowerName && (
                    <div className="mt-2 flex items-center gap-1.5 text-xs text-amber-600 bg-amber-50 rounded-md px-2 py-1 w-fit">
                      <User className="h-3 w-3" />
                      {item.borrowerName}
                      {item.lentAt && <> · {new Date(item.lentAt).toLocaleDateString()}</>}
                    </div>
                  )}
                  {item.status === "returned" && item.returnedAt && (
                    <div className="mt-2 flex items-center gap-1.5 text-xs text-blue-600 bg-blue-50 rounded-md px-2 py-1 w-fit">
                      <Check className="h-3 w-3" />
                      Returned {new Date(item.returnedAt).toLocaleDateString()}
                    </div>
                  )}
                </div>
                <QrCode className="h-4 w-4 text-gray-300 group-hover:text-primary-400 transition flex-shrink-0" />
              </div>
            </Link>
          ))}
        </div>
      )}

      {/* Borrowed items detail */}
      {filtered.some((i) => i.status === "lent") && (
        <div className="mt-8">
          <h2 className="text-lg font-semibold text-gray-900 mb-3">Currently Borrowed</h2>
          <div className="space-y-2">
            {filtered
              .filter((i) => i.status === "lent")
              .map((item) => (
                <div key={item.id} className="card p-4 bg-amber-50/30 border-amber-200">
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="font-semibold text-gray-900">{item.name}</p>
                      <p className="text-xs text-gray-500">{item.gemach.name}</p>
                      <div className="mt-2 space-y-1">
                        <div className="flex items-center gap-1.5 text-sm text-gray-700">
                          <User className="h-3.5 w-3.5 text-gray-400" />
                          {item.borrowerName}
                        </div>
                        {item.borrowerPhone && (
                          <div className="flex items-center gap-1.5 text-sm text-gray-700">
                            <Phone className="h-3.5 w-3.5 text-gray-400" />
                            {item.borrowerPhone}
                          </div>
                        )}
                        {item.borrowerEmail && (
                          <div className="flex items-center gap-1.5 text-sm text-gray-700">
                            <Mail className="h-3.5 w-3.5 text-gray-400" />
                            {item.borrowerEmail}
                          </div>
                        )}
                        {item.lentAt && (
                          <p className="text-xs text-gray-500">
                            Borrowed {new Date(item.lentAt).toLocaleDateString()}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-2">
                      <a
                        href={`https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(
