  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    fetch(`/api/items/${id}`)
      .then((r) => r.json())
      .then((d) => { setItem(d.item); setLoading(false); })
      .catch(() => setLoading(false));
  }, [id]);

